```sql
SELECT (
  SELECT SUM(flown) FROM turnaround.mart_inherited_month WHERE carrier = 'AS' AND year = 2025
) AS AS_flown,
(
  SELECT SUM(flown) FROM turnaround.mart_inherited_month WHERE carrier = 'G4' AND year = 2025
) AS G4_flown
FROM turnaround.mart_inherited_month
WHERE year = 2025;
